#!/usr/bin/env bash
# Installs the vLLM-SR workshop (lab 01) on a lab VM so it starts by itself at every boot.
# Run once while preparing the image:  sudo bash vllm_sr_lab_install.sh
#
# Generated by make-installer.sh from installer-template.sh and setup.sh; edit those, not this file.
#
# Each lab instance gets its own endpoint and key from the lab platform: a lifecycle action
# writes them to /etc/vllm-sr-lab.env at launch. Nothing secret is stored in the image.
#   FOUNDRY_ENDPOINT=<full chat completions URL>
#   FOUNDRY_API_KEY=<this instance's key>
#   ROUTINE_DEPLOYMENT=<optional; default FW-Qwen3.8-27B>
#   REASONING_DEPLOYMENT=<optional; default FW-GLM-5.3-Flash>
# Only these names (and FOUNDRY_PATH) are read; the file is parsed, never executed.
#
# At boot the service waits for that file, exports the values to every new terminal
# (/etc/profile.d/vllm-sr-lab.sh), runs ~/setup.sh, and writes ~/WORKSHOP-READY.txt with the
# links and the Dashboard login; at desktop login the notebook opens in the browser as soon as
# that file appears. Log: /var/log/vllm-sr-lab.log
# Before committing the image, run: sudo vllm-sr-lab-scrub
set -euo pipefail
[ "$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }
LAB_USER="${LAB_USER:-${SUDO_USER:-}}"
[ -n "$LAB_USER" ] && [ "$LAB_USER" != root ] || { echo "run with sudo from the lab user's account (or set LAB_USER)"; exit 1; }
LAB_HOME="$(getent passwd "$LAB_USER" | cut -d: -f6)"
[ -d "$LAB_HOME" ] || { echo "no home directory for $LAB_USER"; exit 1; }

# setup.sh (sha @@SETUP_SHA@@); written in place so its owner stays the lab user.
cat > "$LAB_HOME/setup.sh" <<'VLLM_SR_SETUP_SH'
@@SETUP_SH@@
VLLM_SR_SETUP_SH
chown "$LAB_USER": "$LAB_HOME/setup.sh"
echo "setup.sh sha: $(sha256sum "$LAB_HOME/setup.sh" | cut -c1-12) (expected @@SETUP_SHA@@)"

cat > /usr/local/bin/vllm-sr-lab-start <<'VLLM_SR_START'
#!/usr/bin/env bash
# Boot-time start for the vLLM-SR workshop; installed by vllm_sr_lab_install.sh.
set -u
ENV_FILE="${VLLM_SR_ENV_FILE:-/etc/vllm-sr-lab.env}"
PROFILE="${VLLM_SR_PROFILE:-/etc/profile.d/vllm-sr-lab.sh}"
LAB_USER="${VLLM_SR_LAB_USER:-labuser}"
LAB_HOME="${VLLM_SR_LAB_HOME:-$(getent passwd "$LAB_USER" | cut -d: -f6)}"
SETUP="${VLLM_SR_SETUP:-$LAB_HOME/setup.sh}"
WAIT_SECONDS="${VLLM_SR_WAIT_SECONDS:-1800}"
READY="$LAB_HOME/WORKSHOP-READY.txt"
NAMES="FOUNDRY_ENDPOINT FOUNDRY_API_KEY FOUNDRY_PATH ROUTINE_DEPLOYMENT REASONING_DEPLOYMENT"
LOGIN="admin@workshop.local / workshop2026"   # the Dashboard login setup.sh sets

echo "$(date -u +%FT%TZ) start: waiting up to ${WAIT_SECONDS}s for $ENV_FILE"
rm -f "$READY"
waited=0
while [ ! -s "$ENV_FILE" ] && [ "$waited" -lt "$WAIT_SECONDS" ]; do
  sleep 5; waited=$((waited + 5))
done
[ -s "$ENV_FILE" ] || { echo "no $ENV_FILE after ${WAIT_SECONDS}s; not starting"; exit 1; }

# Read NAME=value lines without executing the file, so a value can hold any character.
while IFS= read -r line || [ -n "$line" ]; do
  line="${line%$'\r'}"
  case "$line" in ''|'#'*) continue ;; esac
  name="${line%%=*}"; value="${line#*=}"
  name="${name#export }"
  case "$value" in \"*\") value="${value:1:${#value}-2}" ;; \'*\') value="${value:1:${#value}-2}" ;; esac
  case " $NAMES " in
    *" $name "*) export "$name=$value"; echo "  read $name" ;;
    *) echo "  ignored $name" ;;
  esac
done < "$ENV_FILE"
for v in FOUNDRY_ENDPOINT FOUNDRY_API_KEY; do
  [ -n "${!v:-}" ] || { echo "$ENV_FILE has no $v; not starting"; exit 1; }
done
export ROUTINE_DEPLOYMENT="${ROUTINE_DEPLOYMENT:-FW-Qwen3.8-27B}"
export REASONING_DEPLOYMENT="${REASONING_DEPLOYMENT:-FW-GLM-5.3-Flash}"

# Every new terminal gets the same values, so `bash ~/setup.sh` also works by hand.
umask 022
{
  echo "# Written at boot by vllm-sr-lab-start from $ENV_FILE; do not edit."
  for v in $NAMES; do
    [ -n "${!v:-}" ] && printf 'export %s=%q\n' "$v" "${!v}"
  done
} > "$PROFILE"
chmod 644 "$PROFILE"

export HOME="$LAB_HOME"
cd "$LAB_HOME" || exit 1
echo "$(date -u +%FT%TZ) running $SETUP (routine: $ROUTINE_DEPLOYMENT, reasoning: $REASONING_DEPLOYMENT)"
bash "$SETUP"
rc=$?
echo "$(date -u +%FT%TZ) setup exited $rc"
[ "$rc" = 0 ] || exit "$rc"

printf 'The workshop is running.\n\nNotebook:    http://localhost:8888/lab/tree/route-one-agent-across-two-models-v3.ipynb\nDashboard:   http://localhost:9000\nDashboard login: %s\n' "$LOGIN" > "$READY"
chown "$LAB_USER": "$READY" 2>/dev/null || true
echo "$(date -u +%FT%TZ) ready: $READY"
VLLM_SR_START
chmod 755 /usr/local/bin/vllm-sr-lab-start

cat > /usr/local/bin/vllm-sr-lab-scrub <<VLLM_SR_SCRUB
#!/usr/bin/env bash
# Clears per-instance state before the image is committed: key file, exported values, the
# running workshop, the workshop folder (it is filled again at launch) and shell history.
# Keeps the workshop image, ~/setup.sh and the boot service.
set -u
[ "\$(id -u)" = 0 ] || { echo "run with sudo"; exit 1; }
systemctl stop vllm-sr-lab.service 2>/dev/null || true
docker rm -f vllm-sr >/dev/null 2>&1 || true
rm -f /etc/vllm-sr-lab.env /etc/profile.d/vllm-sr-lab.sh "$LAB_HOME/WORKSHOP-READY.txt" /var/log/vllm-sr-lab.log
rm -rf "$LAB_HOME/rules-to-reasoning-workshop"
# Left over from the earlier GPU-image workshop, if present.
rm -f "$LAB_HOME/foundry_proxy.py" "$LAB_HOME/.vllm_sr_dashboard"
rm -f "$LAB_HOME/.bash_history" /root/.bash_history
echo "scrubbed; workshop image kept: \$(docker image ls --format '{{.Repository}}@{{.Digest}}' | grep vllm-sr-rules-to-reasoning-d3 | head -1)"
echo "now close the terminal (its history is in memory) and commit"
VLLM_SR_SCRUB
chmod 755 /usr/local/bin/vllm-sr-lab-scrub

# At desktop login: wait until the workshop is ready, then open the notebook in the browser,
# so the student only has to log in.
cat > /usr/local/bin/vllm-sr-lab-open <<'VLLM_SR_OPEN'
#!/usr/bin/env bash
# Opens the workshop notebook once ~/WORKSHOP-READY.txt appears (up to 20 minutes).
URL="http://localhost:8888/lab/tree/route-one-agent-across-two-models-v3.ipynb"
for _ in $(seq 1 240); do
  [ -f "$HOME/WORKSHOP-READY.txt" ] && break
  sleep 5
done
[ -f "$HOME/WORKSHOP-READY.txt" ] || exit 0
sleep 3
xdg-open "$URL" >/dev/null 2>&1 || firefox "$URL" >/dev/null 2>&1 &
VLLM_SR_OPEN
chmod 755 /usr/local/bin/vllm-sr-lab-open
mkdir -p /etc/xdg/autostart
cat > /etc/xdg/autostart/vllm-sr-lab-open.desktop <<'VLLM_SR_DESKTOP'
[Desktop Entry]
Type=Application
Name=vLLM-SR Workshop
Comment=Opens the workshop notebook when it is ready
Exec=/usr/local/bin/vllm-sr-lab-open
X-GNOME-Autostart-enabled=true
NoDisplay=true
VLLM_SR_DESKTOP

cat > /etc/systemd/system/vllm-sr-lab.service <<VLLM_SR_UNIT
[Unit]
Description=From Rules to Reasoning workshop
Wants=network-online.target
After=network-online.target docker.service

[Service]
Type=oneshot
RemainAfterExit=yes
Environment=VLLM_SR_LAB_USER=$LAB_USER
ExecStart=/usr/local/bin/vllm-sr-lab-start
StandardOutput=append:/var/log/vllm-sr-lab.log
StandardError=append:/var/log/vllm-sr-lab.log
TimeoutStartSec=0

[Install]
WantedBy=multi-user.target
VLLM_SR_UNIT

systemctl daemon-reload
systemctl enable vllm-sr-lab.service
echo "installed for $LAB_USER: ~/setup.sh, vllm-sr-lab.service (starts at boot), vllm-sr-lab-scrub"
echo "test now: write /etc/vllm-sr-lab.env, then: sudo systemctl restart vllm-sr-lab; tail -f /var/log/vllm-sr-lab.log"
